/* ---------- Workspace rail ---------- */
/* a slim rail of icons that pins open into a sidebar with labels. Everything in it sits on one 32px column (owner, 18 Nov):
   the workspace's logo tile, each item's icon, the running agents' marks and the pin are centred in it, 12px in from the
   rail's edge, and every label starts 10px after it, where the workspace's name does; an item's hover and the marker that
   glides to the open item are the rail's width less 8px each side. A count sits beside its icon, never over it: a dot while
   the rail is narrow, the number at the row's end once it is open. The page beside it is 16px in from the card's edges */
.wrx{display:flex}
.wrx-rail{width:56px;flex:none;display:flex;flex-direction:column;gap:2px;padding:8px;border-right:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);transition:width var(--dm-t) var(--dm-ease);overflow:hidden}
.wrx.wide .wrx-rail{width:188px}
.wrx-ws{display:flex;align-items:center;gap:10px;padding:4px var(--dm-s-2) 10px 4px;white-space:nowrap}
.wrx-lg .logo{width:18px;height:18px}
.wrx-lg{width:32px;height:32px;border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-ink);color:var(--dm-on-ink);display:grid;place-items:center;font-weight:500;flex:none}
.wrx-lb{flex:1;min-width:0;white-space:nowrap;opacity:0;transform:translateX(-6px);filter:blur(3px);transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease),filter var(--dm-t-fast);display:flex;flex-direction:column;font-size:13px;line-height:1.3;overflow:hidden;text-overflow:ellipsis}
.wrx-lb .muted{font-size:11.5px}
.wrx.wide .wrx-lb{opacity:1;transform:none;filter:none;transition-delay:.08s}
.wrx-nav{display:flex;flex-direction:column;gap:2px;position:relative}
.wrx-ind{position:absolute;left:0;right:0;height:36px;border-radius:calc(11px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-chip);transition:top var(--dm-t) var(--dm-ease);top:0}
.wrx-i{position:relative;display:flex;align-items:center;gap:10px;height:36px;padding:0 var(--dm-s-2) 0 4px;border-radius:calc(11px * var(--dm-rk-l,var(--dm-rk)));color:var(--dm-fg2);white-space:nowrap;transition:color var(--dm-t-fast) var(--dm-ease),background-color var(--dm-t-fast) var(--dm-ease)}
/* the icon centred in the 32px column */
.wrx-i>.i{margin:0 9px}
@media (hover:hover) and (pointer:fine){.wrx-i:hover{color:var(--dm-fg)}}
@media (hover:hover) and (pointer:fine){.wrx-i:not(.on):hover{background:var(--dm-row)}}
.wrx-i.on{color:var(--dm-fg)}
/* the count: a dot beside the icon while the rail is narrow, the number at the row's end once it is open */
.wrx-i .bd{position:absolute;top:50%;left:30px;min-width:6px;height:6px;padding:0;border-radius:var(--dm-r-pill);background:var(--dm-accent);color:var(--dm-on-accent);font-size:0;font-weight:500;line-height:18px;text-align:center;transform:translateY(-50%);transition:left var(--dm-t) var(--dm-ease),min-width var(--dm-t) var(--dm-ease),height var(--dm-t) var(--dm-ease),padding var(--dm-t) var(--dm-ease),font-size var(--dm-t) var(--dm-ease)}
.wrx.wide .wrx-i .bd{left:calc(100% - 26px);min-width:18px;height:18px;padding:0 5px;font-size:10.5px}
:is(.wrx-i,.wrx-run) .wrx-lb{flex-direction:row;text-align:left}
.wrx-i:has(.bd) .wrx-lb{margin-right:var(--dm-s-6)}
.wrx-sp{flex:1;min-height:var(--dm-s-3)}
.wrx-runs{display:flex;flex-direction:column;gap:2px;margin-bottom:6px}
/* the section's label, the muted label type, on the column's left edge; while the rail is narrow a short hairline in the
   column takes its place, so pinning the rail open never changes its height */
.wrx-lbh{position:relative;flex:none;height:24px;padding:0 4px var(--dm-s-2);font-size:11.5px;line-height:16px;color:transparent;white-space:nowrap;overflow:hidden;transition:color var(--dm-t-fast) var(--dm-ease)}
.wrx-lbh::before{content:"";position:absolute;left:12px;top:7.5px;width:16px;height:1px;background:var(--dm-line);transition:opacity var(--dm-t-fast) var(--dm-ease)}
.wrx.wide .wrx-lbh{color:var(--dm-muted);transition-delay:.08s}
.wrx.wide .wrx-lbh::before{opacity:0}
.wrx-run{display:flex;align-items:center;gap:10px;height:32px;padding:0 var(--dm-s-2) 0 4px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:12.5px;color:var(--dm-fg2);white-space:nowrap;transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.wrx-run:hover{background:var(--dm-row);color:var(--dm-fg)}}
.wrx-run .think{color:var(--dm-accent-mark,var(--dm-accent));margin:0 9px}
.wrx-pin svg{transition:transform var(--dm-t) var(--dm-ease)}
.wrx.wide .wrx-pin svg{transform:scaleX(-1)}
.wrx-main{flex:1;min-width:0;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:14px}
.wrx-mh{font-size:14px;line-height:20px;font-weight:500}
.wrx-sk{display:flex;flex-direction:column;gap:9px}
.wrx-sk i{display:block;height:9px;border-radius:var(--dm-r-tiny,5px);background:var(--dm-chip)}
.wrx-sk i.b{height:120px;width:100%;border-radius:calc(14px * var(--dm-rk-l,var(--dm-rk)));margin-top:6px}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.wrx :is(.wrx-i,.wrx-run):active{transform:none}
/* Clean (owner, 17 and 18 Nov): the rail an off-white strip with a hairline on its right, the open item a white knob with
   a hairline that glides to it, as a switcher's does, and a hover the quiet grey; the rows' corners follow the card's, 8px
   in (22px less 8); labels fade in without a blur; the page beside it is white, 16px in */
:root[data-style="clean"] .wrx-rail,:root [data-style="clean"] .wrx-rail,:root [data-style="clean"].wrx-rail{background:var(--dm-strip);border-right-color:var(--dm-line);border-radius:var(--dm-r-card) 0 0 var(--dm-r-card)}
:root[data-style="clean"] .wrx-lg,:root [data-style="clean"] .wrx-lg,:root [data-style="clean"].wrx-lg{border-radius:10px}
:root[data-style="clean"] .wrx-lb,:root [data-style="clean"] .wrx-lb,:root [data-style="clean"].wrx-lb{filter:none}
:root[data-style="clean"] .wrx-ind,:root [data-style="clean"] .wrx-ind,:root [data-style="clean"].wrx-ind{background:var(--dm-knob);box-shadow:var(--dm-knob-shadow);border-radius:calc(var(--dm-r-card) - 8px);transition:top var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] :is(.wrx-i,.wrx-run),:root [data-style="clean"] :is(.wrx-i,.wrx-run),:root [data-style="clean"]:is(.wrx-i,.wrx-run){border-radius:calc(var(--dm-r-card) - 8px)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] :is(.wrx-i:not(.on):hover,.wrx-run:hover),:root [data-style="clean"] :is(.wrx-i:not(.on):hover,.wrx-run:hover),:root [data-style="clean"]:is(.wrx-i:not(.on):hover,.wrx-run:hover){background:var(--dm-row)}}
:root[data-style="clean"] .wrx-sk i,:root [data-style="clean"] .wrx-sk i,:root [data-style="clean"].wrx-sk i{background:var(--dm-ghost)}
:root[data-style="clean"] .wrx-sk i.b,:root [data-style="clean"] .wrx-sk i.b,:root [data-style="clean"].wrx-sk i.b{border-radius:calc(var(--dm-r-card) - 6px)}

DM.def('workspace-rail', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{panel}', I('panel'));
  // Clean's one hover: a highlight that glides from row to row (hoverGlide)
  c.offs.push(hoverGlide($('.wrx-rail', r), '.wrx-i,.wrx-run', { keep:'.on' }));
  const N = [['home','Home',0],['spark','Agent',2],['layers','Projects',0],['figma','Frames',0],['book','Memory',0],['gear','Settings',0]];
  const nav = $('.wrx-nav', r), ind = $('.wrx-ind', r), root = $('.wrx', r), mh = $('.wrx-mh', r), pin = $('.wrx-pin', r);
  // each item: its icon in the rail's column, its label, and a count beside the icon (a dot while the rail is narrow)
  nav.insertAdjacentHTML('beforeend', N.map((n, i) => `<button class="wrx-i${i === 1 ? ' on' : ''}" data-i="${i}" aria-label="${n[1]}"${i === 1 ? ' aria-current="page"' : ''} data-tip="${n[1]}">${I(n[0])}<span class="wrx-lb">${n[1]}</span>${n[2] ? `<span class="bd" aria-hidden="true">${n[2]}</span>` : ''}</button>`).join(''));
  $('.wrx-runs', r).insertAdjacentHTML('beforeend', ['Pricing audit','Token export'].map(t => `<button class="wrx-run" data-tip="${t}"><span class="think on"><i></i><i></i><i></i><i></i></span><span class="wrx-lb">${t}</span></button>`).join(''));
  const items = $$('.wrx-i[data-i]', nav);
  function go(b){ items.forEach(x => { x.classList.toggle('on', x === b); if (x === b) x.setAttribute('aria-current', 'page'); else x.removeAttribute('aria-current'); }); ind.style.top = b.offsetTop + 'px'; swap(mh, N[+b.dataset.i][1]); const bd = $('.bd', b); if (bd){ bd.classList.add('leave'); c.later(300, () => bd.remove()); } }
  items.forEach(b => b.onclick = () => go(b));
  const tipSync = () => $$('[data-tip]', $('.wrx-rail', r)).forEach(el => { if (!el.dataset.t0) el.dataset.t0 = el.dataset.tip; if (root.classList.contains('wide') && !el.classList.contains('wrx-pin')) el.removeAttribute('data-tip'); else el.dataset.tip = el.dataset.t0; });
  const pinned = w => { root.classList.toggle('wide', w); pin.setAttribute('aria-expanded', w); pin.dataset.t0 = w ? 'Collapse' : 'Pin open'; tipSync(); };
  pin.onclick = () => pinned(!root.classList.contains('wide'));
  mh.textContent = 'Agent'; requestAnimationFrame(() => ind.style.top = items[1].offsetTop + 'px');
  // the preview pins the rail open once on its own, unless you take over first
  c.auto(1500, () => pinned(true));
});
